"""Read-only final Credit Note and SO invoiced-quantity verification."""
from migrate_pysb_credit_notes import Run,OUT,ROOT,load
from execute_pysb_stock_migration import index,rid,save,require
import html,json
def main():
 m=Run();p=load(OUT/'plan.json');require(len(m.j['documents'])==17 and all(x['status']=='verified_posted' for x in m.j['documents'].values()),'Incomplete');docs=p['documents'];rows=[]
 for d in docs:
  s=d['source'];t=m.j['documents'][str(s['id'])]['target_id'];w=m.b.read('account.move',[t],['name','state','company_id','date','invoice_date','amount_total'])[0];require(w['state']=='posted' and rid(w['company_id'])==1 and abs(w['amount_total']-s['amount_total'])<.00501,'Credit Note mismatch');rows.append({'source_id':s['id'],'source_name':s['name'],'target_id':t,'target_name':w['name'],'date':w['date'],'total':w['amount_total'],'state':w['state']})
 ids=[x['id'] for x in load(ROOT/'outputs/pysb-stock-migration-20261012/v14-prod-snapshot.json')['sol']];mp=m.maps['sale.order.line'];a=index(m.a.read('sale.order.line',ids,['order_id','qty_invoiced']));b=index(m.b.read('sale.order.line',[mp[i] for i in ids],['qty_invoiced']));diff=[{'source_line':i,'target_line':mp[i],'order':a[i]['order_id'][1],'source_qty':a[i]['qty_invoiced'],'target_qty':b[mp[i]]['qty_invoiced'],'delta':b[mp[i]]['qty_invoiced']-a[i]['qty_invoiced']} for i in ids if abs(b[mp[i]]['qty_invoiced']-a[i]['qty_invoiced'])>.00501];result={'summary':{'credit_notes_posted':len(rows),'so_lines_checked':len(ids),'qty_invoiced_mismatch':len(diff),'payments_reconciliation':False},'credit_notes':rows,'remaining_differences':diff};save(OUT/'final-report.json',result)
 body='<meta charset="utf-8"><title>PYSB — Credit Note</title><style>body{font:14px Arial;margin:24px}td,th{padding:8px;border:1px solid #ddd}table{border-collapse:collapse}</style><h1>Pao Yeang — 17 Credit Note</h1><p>Đã post trên staging; giữ ngày, dòng hàng, giá, chiết khấu, lượng, liên kết SO và hóa đơn gốc khi nguồn có liên kết. Giữ E-invoice metadata; không gửi lại E-invoice, không payment/reconcile.</p><pre>'+html.escape(json.dumps(result['summary'],ensure_ascii=False,indent=2))+'</pre><table><tr><th>v14</th><th>v19</th><th>Ngày</th><th>Tổng</th></tr>'
 for r in rows:body+=f'<tr><td><a href="http://175.145.85.151/web#id={r["source_id"]}&amp;model=account.move&amp;view_type=form">{html.escape(r["source_name"])}</a></td><td><a href="https://py-staging.odoo.com/web#id={r["target_id"]}&amp;model=account.move&amp;view_type=form">{html.escape(r["target_name"])}</a></td><td>{r["date"]}</td><td>{r["total"]}</td></tr>'
 body+='</table><h2>Lượng invoiced SO còn lệch</h2><pre>'+html.escape(json.dumps(diff,ensure_ascii=False,indent=2))+'</pre>';(OUT/'PYSB_Credit_Note_Result.html').write_text(body,encoding='utf8');print(json.dumps(result,ensure_ascii=False),flush=True)
if __name__=='__main__':main()
